CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim
COMMENT 'Harbour motor claims. Grain: One row per claim. Conformed from HARBOUR_CC (lr_serverless_aws_us_catalog.bricksurance_harbour_cc.cc_claim) by mapping harbour_cc; column names and definitions are the core concept claim. Owner Harbour Mutual, Head of Claims; certified.'
AS
SELECT concat('HARBOUR_CC:', c.PublicID) AS claim_id,
       c.ClaimNumber AS claim_number,
       concat('HARBOUR_PC:', p.PublicID) AS policy_id,
       CASE c.State WHEN 'open' THEN 'OPEN' ELSE 'CLOSED' END AS claim_status_code,
       CASE c.LossCause WHEN 'vehcollision' THEN 'COLLISION' WHEN 'theft' THEN 'THEFT' WHEN 'glassbreakage' THEN 'GLASS'
                        WHEN 'fire' THEN 'FIRE' ELSE 'LIABILITY_INCIDENT' END AS cause_of_loss_code,
       c.LossDate AS loss_date, c.ReportedDate AS reported_date, 'HARBOUR_CC' AS source_system_code,
       CASE c.LossCause WHEN 'vehcollision' THEN 'AD' WHEN 'theft' THEN 'THEFT' WHEN 'propertydamage' THEN 'TPPD'
                        WHEN 'bodilyinjury' THEN 'TPBI' WHEN 'glassbreakage' THEN 'WINDSCREEN' ELSE 'FIRE' END AS peril_code,
       c.LossLocationPostalCode AS loss_postcode_area
FROM lr_serverless_aws_us_catalog.bricksurance_harbour_cc.cc_claim c
LEFT JOIN lr_serverless_aws_us_catalog.bricksurance_harbour_pc.pc_policyperiod p ON p.PolicyNumber = c.PolicyNumber;

