CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction
COMMENT 'Claim centre transactions as core claim transactions. Payment with CostType expense is a claims-handling cost; Payment with claimcost is indemnity and also generates the core''s reserve release. Grain: One row per transaction, plus one reserve release per payment (core convention). Conformed from HARBOUR_CC (lr_serverless_aws_us_catalog.bricksurance_harbour_cc.cc_transaction) by mapping harbour_cc; column names and definitions are the core concept claim_transaction. Owner Harbour Mutual, Head of Claims; certified.'
AS
SELECT concat('HARBOUR_CC:', PublicID) AS claim_transaction_id,
       concat('HARBOUR_CC:', ClaimID) AS claim_id,
       CASE WHEN TransactionType = 'Payment' AND CostType = 'expense' THEN 'EXPENSE_PAYMENT'
            WHEN TransactionType = 'Payment' THEN 'INDEMNITY_PAYMENT'
            WHEN TransactionType = 'Reserve' THEN 'CASE_RESERVE_MOVEMENT' ELSE 'RECOVERY' END AS claim_transaction_type_code,
       Amount AS amount, 'GBP' AS currency_code, CAST(CreateTime AS DATE) AS transaction_date, 'HARBOUR_CC' AS source_system_code,
       CASE WHEN CostType = 'expense' THEN 'FEES' ELSE 'CLAIM_COST' END AS head_of_damage_code,
       'OWN_DAMAGE' AS claim_feature_type_code
FROM lr_serverless_aws_us_catalog.bricksurance_harbour_cc.cc_transaction
UNION ALL
SELECT concat('HARBOUR_CC:', PublicID, ':REL'), concat('HARBOUR_CC:', ClaimID), 'CASE_RESERVE_MOVEMENT',
       -Amount, 'GBP', CAST(CreateTime AS DATE), 'HARBOUR_CC', 'CLAIM_COST', 'OWN_DAMAGE'
FROM lr_serverless_aws_us_catalog.bricksurance_harbour_cc.cc_transaction
WHERE TransactionType = 'Payment' AND CostType = 'claimcost';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.claim_transaction_id IS 'Identifier for the claim transaction.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.claim_id IS 'Claim the movement belongs to.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.claim_transaction_type_code IS 'Kind of financial movement.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.amount IS 'Signed amount in the transaction currency. Reserve increases positive, reserve releases negative; payments positive; recoveries negative from the insurer''s cost perspective.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.currency_code IS 'Currency of the amount.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.transaction_date IS 'Date the movement was booked.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.source_system_code IS 'System of record the movement originates from.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.head_of_damage_code IS 'Harbour does not record head of damage; CostType (claimcost / expense) is carried in its place.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_claim_transaction.claim_feature_type_code IS 'Not available from Harbour''s claim centre at transaction level; defaulted to OWN_DAMAGE and said so.';

